/// One diode of the curve's breakpoint network.
///
/// It switches on at `at`
/// (curve-input units) and changes the slope by `slope` over a soft knee
/// `knee` wide. `leak` = σ(−at/knee) is its slope already present at zero and
/// `base` = softplus(−at/knee) its value there, both removed so the curve
/// passes through zero at unity slope.
pub struct Breakpoint {
    pub at: f64,
    pub slope: f64,
    pub knee: f64,
    pub leak: f64,
    pub base: f64,
}

